package got.client;
import got.network.C2SBrandingNamePacket;import got.network.GOTNetwork;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.components.EditBox;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import net.minecraft.world.InteractionHand;
public final class GOTBrandingIronScreen extends Screen{public static void open(InteractionHand h){net.minecraft.client.Minecraft.getInstance().setScreen(new GOTBrandingIronScreen(h));}private final InteractionHand hand;private EditBox name;public GOTBrandingIronScreen(InteractionHand h){super(Component.translatable("gui.got.branding_iron"));hand=h;}protected void init(){name=new EditBox(font,width/2-100,height/2-20,200,20,Component.translatable("gui.got.branding_iron.name"));name.setMaxLength(64);addRenderableWidget(name);addRenderableWidget(Button.builder(Component.translatable("gui.done"),b->{GOTNetwork.CHANNEL.sendToServer(new C2SBrandingNamePacket(hand==InteractionHand.OFF_HAND,name.getValue()));onClose();}).bounds(width/2-50,height/2+15,100,20).build());setInitialFocus(name);}public void render(GuiGraphics g,int x,int y,float f){renderBackground(g);g.drawCenteredString(font,title,width/2,height/2-45,0xffffff);super.render(g,x,y,f);}public boolean isPauseScreen(){return false;}}
